<template><view class="page"><view class="search glass"><input v-model="q" placeholder="搜索书名、作者、标签" @confirm="load"/><button class="btn" @click="load">搜索</button></view><view class="chips"><text v-for="c in options.categories" :key="c" @click="q=c;load()" class="chip">{{c}}</text></view><BookCard v-for="b in books" :key="b.id" :book="b" @tap="goDetail" /></view></template>
<script setup>import { ref,onMounted } from 'vue'; import { request } from '../../api/request'; import BookCard from '../../components/BookCard.vue'; const q=ref(''); const books=ref([]); const options=ref({categories:[]}); async function load(){const r=await request('/books?limit=50'+(q.value?'&q='+encodeURIComponent(q.value):'')); books.value=r.items||[]} async function init(){options.value=await request('/books/meta/options'); await load()} function goDetail(b){uni.navigateTo({url:'/pages/detail/detail?id='+b.id})} onMounted(init)</script><style scoped>.search{display:flex;gap:16rpx;padding:20rpx;margin:16rpx}.search input{flex:1;background:#fff;border-radius:999rpx;padding:18rpx 24rpx}.chips{display:flex;gap:12rpx;flex-wrap:wrap;margin:16rpx}.chip{padding:10rpx 18rpx;background:#fff;border-radius:999rpx;color:#475467;font-weight:800}</style>
